import{_ as a,o as d,c as r,a2 as l}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"تعلیم کی ضمانت کا قانون","description":"","frontmatter":{},"headers":[],"relativePath":"ur/43-教育保障法.md","filePath":"ur/43-教育保障法.md","lastUpdated":1789183869000}'),e={name:"ur/43-教育保障法.md"};function i(o,t,h,n,s,u){return d(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="تعلیم-کی-ضمانت-کا-قانون" tabindex="-1">تعلیم کی ضمانت کا قانون <a class="header-anchor" href="#تعلیم-کی-ضمانت-کا-قانون" aria-label="Permalink to &quot;تعلیم کی ضمانت کا قانون&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>43</td></tr><tr><td>ماڈیول</td><td>قانونی نظام اور گورننس کا فریم ورک</td></tr><tr><td>بنیادی کلیدی الفاظ</td><td>تعلیم کا حق، سمبیوسس تعلیم، سادھنہ کی وراثت، تاحیات تعلیم، تعلیم کی انصاف</td></tr></tbody></table><h2 id="أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" tabindex="-1">أولاً. قانون سازی کا مقصد اور بنیادی اصول <a class="header-anchor" href="#أولاً-قانون-سازی-کا-مقصد-اور-بنیادی-اصول" aria-label="Permalink to &quot;أولاً. قانون سازی کا مقصد اور بنیادی اصول&quot;">​</a></h2><p>《تعلیم کی ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے پانچ معاون قوانین میں سے ایک ہے، اور اس کا مقصد ہینگیوانژو کے اندر تمام زندگی کے تعلیم کے حق کی ضمانت کرنا، &quot;سمبیوسس ارتقاء&quot; کو بنیادی تصور کے ساتھ تعلیم کا نظام قائم کرنا، اور تمام نسلوں کی مشترکہ ترقی کے لیے علم اور باصلاحیت افراد کی معاونت فراہم کرنا ہے۔</p><p>یہ قانون درج ذیل بنیادی اصول قائم کرتا ہے:</p><table tabindex="0"><thead><tr><th>اصول</th><th>مواد</th></tr></thead><tbody><tr><td>تعلیم کی انصاف کا اصول</td><td>تمام زندگی، نسل، سادھنہ کی سطح، اصل سے قطع نظر، یکساں تعلیمی مواقع حاصل کرتی ہے</td></tr><tr><td>صلاحیت کے مطابق تعلیم کا اصول</td><td>ہر زندگی کی صلاحیت کے فرق اور ارتقاء کے راستے کے انتخاب کا احترام کرنا، ذاتی نوعیت کی تعلیمی منصوبہ بندی فراہم کرنا</td></tr><tr><td>علم اور عمل کی وحدت کا اصول</td><td>نظریاتی علم اور عملی سادھنہ کو یکجا کرنا، حقیقت سے الگ خالی باتوں کی تعلیم کی مخالفت کرنا</td></tr><tr><td>کھلا اور اشتراک کا اصول</td><td>تعلیمی وسائل پوری معاشرے کے لیے کھلے ہیں، تین سو اصل سادھنہ نظام کے بنیادی طریقے مفت سکھائے جاتے ہیں</td></tr><tr><td>تاحیات تعلیم کا اصول</td><td>تعلیم زندگی کے پورے عمل میں جاری رہتی ہے، ہر مرحلے میں مسلسل تعلیم اور صلاحیت میں بہتری کی حمایت کرتی ہے</td></tr><tr><td>ثقافتی تنوع کا اصول</td><td>ہر نسل کے ثقافتی روایات کا احترام کرنا، کثیر الثقافتی تبادلے اور باہمی سیکھنے کی حوصلہ افزائی کرنا</td></tr></tbody></table><h2 id="ثانياً-تعلیم-کے-حق-کی-قانونی-ضمانت" tabindex="-1">ثانياً. تعلیم کے حق کی قانونی ضمانت <a class="header-anchor" href="#ثانياً-تعلیم-کے-حق-کی-قانونی-ضمانت" aria-label="Permalink to &quot;ثانياً. تعلیم کے حق کی قانونی ضمانت&quot;">​</a></h2><p>یہ قانون واضح طور پر مقرر کرتا ہے کہ تعلیم کا حق سمبیوسس آئین کے ذریعے ہر زندگی کو عطا کردہ بنیادی حق ہے، اور ریاست اور تہذیب پر اس حق کے نفاذ کی ضمانت کرنے کی ذمہ داری ہے:</p><ol><li><strong>مفت بنیادی تعلیم</strong>: تمام زندگی کو مفت بنیادی تعلیم حاصل کرنے کا حق ہے، جس میں عام علم، بنیادی سادھنہ طریقے، سمبیوسس تہذیب کے تصور وغیرہ شامل ہیں، تعلیم کی مدت چھ سے بارہ سال ہے، اور نسل کی نشوونما کے چکر کے مطابق ایڈجسٹ کیا جاتا ہے۔</li><li><strong>مفت سادھنہ تعارف</strong>: کائنات کے تین سو اصل سادھنہ نظام کے بنیادی طریقے تمام زندگی کے لیے مفت کھلے ہیں، کوئی تنظیم اور فرد بنیادی سادھنہ طریقوں کو نجی ملکیت کے طور پر قبضہ کر کے وصولی کے ساتھ نہیں سکھا سکتا۔</li><li><strong>اعلیٰ تعلیم کے مواقع کی برابری</strong>: تمام سطحوں اور اقسام کے تعلیمی ادارے داخلے میں نسل، سادھنہ کی سطح، اصل وغیرہ جیسے امتیازی شرائط نہیں بنا سکتے، اور داخلے کے معیار کھلے اور شفاف ہوں گے۔</li><li><strong>خاص تعلیم کی ضمانت</strong>: معذور زندگی، دوسری نسلوں کی زندگی، دور دراز位面 کی زندگی وغیرہ گروپوں کے لیے موافق خاص تعلیمی وسائل اور دور دراز تعلیم کی معاونت فراہم کرنا۔</li><li><strong>تعلیمی امداد کا نظام</strong>: معاشی مشکلات میں مبتلا طلباء کے لیے اسکالرشپ، میرٹ اسکالرشپ اور بلا سود قرض فراہم کرنا، اور اس بات کو یقینی بنانا کہ وہ معاشی وجوہات کی بنا پر تعلیمی موقع سے محروم نہ ہوں۔</li></ol><h2 id="ثالثاً-تعلیم-کے-نظام-کا-ڈھانچہ" tabindex="-1">ثالثاً. تعلیم کے نظام کا ڈھانچہ <a class="header-anchor" href="#ثالثاً-تعلیم-کے-نظام-کا-ڈھانچہ" aria-label="Permalink to &quot;ثالثاً. تعلیم کے نظام کا ڈھانچہ&quot;">​</a></h2><p>اینکر سمبیوسس تہذیب کے تعلیم کا نظام چار سطحوں میں تقسیم ہے، اور ہر سطح کے درمیان نامیاتی طور پر جڑا ہوا ہے:</p><table tabindex="0"><thead><tr><th>سطح</th><th>نام</th><th>مقصد</th><th>مدت</th></tr></thead><tbody><tr><td>پہلی سطح</td><td>ابتدائی تعلیم</td><td>بنیادی علمی صلاحیت اور سمبیوسس شعور کی نشوونما، بنیادی سادھنہ طریقے سکھانا</td><td>3-6 سال</td></tr><tr><td>دوسری سطح</td><td>بنیادی تعلیم</td><td>عام علم اور سادھنہ نظریے کا منظم مطالعہ، انفرادی صلاحیت کی سمت کی دریافت</td><td>6-9 سال</td></tr><tr><td>تیسری سطح</td><td>پیشہ ورانہ تعلیم</td><td>منتخب سادھنہ نظام یا پیشہ ورانہ شعبے میں گہری تعلیم اور مشق</td><td>3-10 سال</td></tr><tr><td>چوتھی سطح</td><td>اعلیٰ سطحی مطالعہ</td><td>اعلیٰ سطح کے سادھکوں اور محققین کے لیے جدید دریافت اور اختراعی مطالعہ</td><td>غیر محدود</td></tr></tbody></table><p>اس کے علاوہ، &quot;مینٹر نیٹ ورک کا نظام&quot; قائم کیا گیا ہے: ایک مخصوص سادھنہ کی سطح تک پہنچنے والے سادھکوں پر ان کی صلاحیت کے دائرے میں ابتدائی سادھکوں کی رہنمائی کرنے کی ذمہ داری ہے، اور رہنمائی کا شراکت مشترکہ پیداوار معاہدے کے نظام کے شراکت کی مقدار میں شمار کیا جاتا ہے، اور متعلقہ وسائل کی تقسیم سے لطف اندوز ہوتا ہے۔</p><h2 id="رابعاً-تعلیمی-ادارے-اور-اساتذہ" tabindex="-1">رابعاً. تعلیمی ادارے اور اساتذہ <a class="header-anchor" href="#رابعاً-تعلیمی-ادارے-اور-اساتذہ" aria-label="Permalink to &quot;رابعاً. تعلیمی ادارے اور اساتذہ&quot;">​</a></h2><ul><li><strong>عوامی تعلیمی ادارے</strong>: ریاست یا تہذیب کی کمیونٹی کے ذریعے قائم، مفت بنیادی تعلیم اور عوامی تعلیمی خدمات کی ذمہ داری، اور فنڈز عوامی جمع کے ذریعے یقینی بنائے جاتے ہیں۔</li><li><strong>نجی تعلیمی ادارے</strong>: سماجی قوتوں کے ذریعے قانون کے مطابق قائم، مناسب فیس وصول کر سکتے ہیں، لیکن انہیں ضرور تعلیم کے محکمہ کی نگرانی قبول کرنی چاہیے، اور جھوٹی تشہیر اور لوٹ مار وصولی نہیں کر سکتے۔</li><li><strong>سادھنہ فرقے</strong>: روایتی سادھنہ تنظیمیں رجسٹریشن کے بعد پیشہ ورانہ تعلیمی ادارے کے طور پر کام کر سکتی ہیں، اور انہیں ضرور تعلیم کے قانون کی دفعات کی تعمیل کرنی چاہیے، اور سادھنہ وسائل کو بند کر کے اجارہ داری نہیں کر سکتیں۔</li><li><strong>اساتذہ کے حقوق اور فرائض</strong>: اساتذہ کو علمی آزادی، مناسب اجرت، پیشہ ورانہ تربیت وغیرہ حقوق حاصل ہیں، اور ایک ہی وقت میں سکھانا اور پڑھانا، مثالی شخصیت بننا، طلباء کی رازداری کی حفاظت کرنا وغیرہ فرائض ہیں۔</li></ul><h2 id="خامساً-تعلیمی-مواد-اور-نصابی-معیار" tabindex="-1">خامساً. تعلیمی مواد اور نصابی معیار <a class="header-anchor" href="#خامساً-تعلیمی-مواد-اور-نصابی-معیار" aria-label="Permalink to &quot;خامساً. تعلیمی مواد اور نصابی معیار&quot;">​</a></h2><p>تعلیمی مواد کو درج ذیل تقاضوں کو پورا کرنا چاہیے:</p><ol><li>سمبیوسس تہذیب کے بنیادی تصور اور لوٹ مار مخالف تعلیم شامل ہو، اور طلباء کی سمبیوسس شعور کی نشوونما ہو۔</li><li>تین سو اصل سادھنہ نظام کے بنیادی نظریے اور تعارفی طریقے شامل ہوں۔</li><li>کائنات کے قوانین،位面 کے علم، حیاتیات وغیرہ عام سائنسی علم شامل ہوں۔</li><li>تمام نسلوں کی تاریخ اور ثقافت شامل ہو، اور نسلوں کے درمیان باہمی افہام اور احترام کو فروغ دے۔</li><li>عملی سادھنہ اور سماجی خدمات کے حصے شامل ہوں، اور علم اور عمل کی وحدت کی صلاحیت کی نشوونما ہو۔</li><li>لوٹ مار سادھنہ کے تصور اور امتیازی فکر کی تبلیغ ممنوع ہے۔</li></ol><h2 id="سادساً-قانونی-ذمہ-داری" tabindex="-1">سادساً. قانونی ذمہ داری <a class="header-anchor" href="#سادساً-قانونی-ذمہ-داری" aria-label="Permalink to &quot;سادساً. قانونی ذمہ داری&quot;">​</a></h2><p>اس قانون کی دفعات کی خلاف ورزی کرنے والے کارروائیاں جرم کی شدت کے مطابق درج ذیل ذمہ داری اٹھائیں گی:</p><ul><li>اسکول جانے کی عمر کی زندگی کو لازمی تعلیم حاصل کرنے سے انکار یا روکنا، اصلاح کا حکم اور سزا۔</li><li>تعلیمی ادارے کی غیر قانونی وصولی، جھوٹی تشہیر، فیس واپس کرنے کا حکم اور جرمانہ، سنگین صورتوں میں تعلیمی ادارے کا لائسنس منسوخ۔</li><li>استاد کی جسمانی سزا یا طلباء کے ساتھ امتیازی سلوک، سزا، سنگین صورتوں میں استاد کی قابلیت منسوخ اور قانونی ذمہ داری عائد۔</li><li>عوامی سادھنہ وسائل کو نجی ملکیت کے طور پر قبضہ کرنا، اجارہ داری اور وصولی، غیر قانونی آمدنی ضبط اور جرمانہ۔</li></ul><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>《تعلیم کی ضمانت کا قانون》 اینکر سمبیوسس تہذیب کے &quot;ہر ایک کے پاس راستہ ہے&quot; کے تصور کی تعلیمی عمل ہے۔ یہ تعلیم کے حق کی ضمانت، سطح بند تعلیم کا نظام بنانے، سادھنہ وسائل کھولنے کے ذریعے، اس بات کو یقینی بناتا ہے کہ ہر زندگی اپنے لیے مناسب ارتقاء کا راستہ حاصل کر سکے، اور تمام نسلوں کی مشترکہ ترقی کے لیے مسلسل علم اور باصلاحیت افراد فراہم کرے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>40-共生宪法总纲 (سمبیوسس آئین کے بنیادی اصول)</li><li>37-共生教育体系 (سمبیوسس تعلیم کا نظام)</li><li>10-三百套本源修炼体系总览 (تین سو اصل سادھنہ نظام کا جائزہ)</li><li>08-人人有路保障体系 (ہر ایک کے پاس راستہ ہے کا ضمانت نظام)</li></ul>',25)])])}const p=a(e,[["render",i]]);export{c as __pageData,p as default};
